#!/bin/sh
# racecar-cli-launcher: GENERATED by `install_cli.py`. DO NOT EDIT; rerun the repo's ./install.
#
# Runs one repo's CLI the way a person types it, from any directory, with no venv to source:
#
#     <pkg>                         the root listing
#     <pkg> <verb> [args]           a root verb
#     <pkg> <noun> [<noun> ...]     a noun's listing
#     <pkg> <noun> <verb> [args]    a noun's verb; --help at any level
#
# The two lines below are the only ones `install_cli.py` fills in. Everything else is read at run
# time from the repo itself: a leading word is a noun when `<pkg>/<noun>/__main__.py` exists,
# which is how `python -m` finds a module, and the verbs are that module's own argparse.
#
# RC_CLI tells the CLI's `lib/cli.py` to print `<pkg> <noun> <verb>` rather than
# `python -m <pkg>.<noun> <verb>`. It carries this shell's pid, which `exec` hands to Python, so
# only that one process reads it: a child process prints exactly what it printed before.
REPO='@REPO@'
PKG='@PKG@'

fail() {
    printf '%s: %s\n' "$PKG" "$1" >&2
    exit 1
}

[ -d "$REPO" ] || fail "no repo at $REPO; run ./install in its new checkout"

# The venv, as racecar.mk picks it: RC_VENV (relative to the repo), else the first of .venv,
# venv, ../venv that exists, else .venv.
if [ -n "${RC_VENV:-}" ]; then
    case $RC_VENV in
        /*) venv=$RC_VENV ;;
        *) venv=$REPO/$RC_VENV ;;
    esac
else
    venv=$REPO/.venv
    for candidate in .venv venv ../venv; do
        if [ -e "$REPO/$candidate" ] || [ -L "$REPO/$candidate" ]; then
            venv=$REPO/$candidate
            break
        fi
    done
fi
python=$venv/bin/python
[ -f "$python" ] && [ -x "$python" ] || fail "no venv Python at $python; run make install in $REPO"

# The package's home: src/ in the src layout, the repo root in the flat layout.
home=$REPO/src
[ -d "$home" ] || home=$REPO

# Leading words that name a noun's module become the module; the first other word ends it.
module=$PKG
path=$home/$PKG
while [ $# -gt 0 ]; do
    case $1 in
        '' | [0-9]* | *[!A-Za-z0-9_]*) break ;;
    esac
    [ -f "$path/$1/__main__.py" ] || break
    module=$module.$1
    path=$path/$1
    shift
done

RC_CLI="$PKG $$"
export RC_CLI
# `-P`: a directory named <pkg> in the caller's cwd cannot shadow the package. The home goes on
# sys.path inside this process only, so child processes inherit no PYTHONPATH from here.
exec "$python" -P -c '
import runpy, sys
home, module = sys.argv[1], sys.argv[2]
sys.path.insert(0, home)
sys.argv = [module, *sys.argv[3:]]
runpy.run_module(module, run_name="__main__", alter_sys=True)
' "$home" "$module" "$@"
